  'Go to Upload, choose your video file, add required details, select category and language, add a thumbnail, then publish. Large files upload in chunks.' => 'ਅੱਪਲੋਡ \'ਤੇ ਜਾਓ, ਆਪਣੀ ਵੀਡੀਓ ਫ਼ਾਈਲ ਚੁਣੋ, ਲੋੜੀਂਦੇ ਵੇਰਵੇ ਸ਼ਾਮਲ ਕਰੋ, ਸ਼੍ਰੇਣੀ ਅਤੇ ਭਾਸ਼ਾ ਚੁਣੋ, ਥੰਬਨੇਲ ਸ਼ਾਮਲ ਕਰੋ, ਫਿਰ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰੋ। ਵੱਡੀਆਂ ਫਾਈਲਾਂ ਟੁਕੜਿਆਂ ਵਿੱਚ ਅੱਪਲੋਡ ਹੁੰਦੀਆਂ ਹਨ।',
  'Guest mode' => 'ਮਹਿਮਾਨ ਮੋਡ',
  'Have a question, feedback, partnership idea, or support request? Send it through the backend form and admins will see it in the Support dashboard.' => 'ਕੋਈ ਸਵਾਲ, ਫੀਡਬੈਕ, ਭਾਈਵਾਲੀ ਵਿਚਾਰ, ਜਾਂ ਸਹਾਇਤਾ ਬੇਨਤੀ ਹੈ? ਇਸਨੂੰ ਬੈਕਐਂਡ ਫਾਰਮ ਰਾਹੀਂ ਭੇਜੋ ਅਤੇ ਪ੍ਰਸ਼ਾਸਕ ਇਸਨੂੰ ਸਪੋਰਟ ਡੈਸ਼ਬੋਰਡ ਵਿੱਚ ਦੇਖਣਗੇ।',
  'High priority' => 'ਉੱਚ ਤਰਜੀਹ',
  'How can I become a creator?' => 'ਮੈਂ ਇੱਕ ਸਿਰਜਣਹਾਰ ਕਿਵੇਂ ਬਣ ਸਕਦਾ ਹਾਂ?',
  'How can we help you?' => 'ਅਸੀਂ ਤੁਹਾਡੀ ਮਦਦ ਕਿਵੇਂ ਕਰ ਸਕਦੇ ਹਾਂ?',
  'How can we help?' => 'ਅਸੀਂ ਕਿਵੇਂ ਮਦਦ ਕਰ ਸਕਦੇ ਹਾਂ?',
  'How data is used' => 'ਡਾਟਾ ਕਿਵੇਂ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ',
  'How do I become a creator?' => 'ਮੈਂ ਇੱਕ ਸਿਰਜਣਹਾਰ ਕਿਵੇਂ ਬਣਾਂ?',
  'How do I report inappropriate content?' => 'ਮੈਂ ਅਣਉਚਿਤ ਸਮੱਗਰੀ ਦੀ ਰਿਪੋਰਟ ਕਿਵੇਂ ਕਰਾਂ?',
  'How do I update password or two-factor authentication?' => 'ਮੈਂ ਪਾਸਵਰਡ ਜਾਂ ਦੋ-ਕਾਰਕ ਪ੍ਰਮਾਣਿਕਤਾ ਨੂੰ ਕਿਵੇਂ ਅੱਪਡੇਟ ਕਰਾਂ?',
  'How do I upload a video?' => 'ਮੈਂ ਇੱਕ ਵੀਡੀਓ ਕਿਵੇਂ ਅਪਲੋਡ ਕਰਾਂ?',
  'How do uploads work?' => 'ਅਪਲੋਡ ਕਿਵੇਂ ਕੰਮ ਕਰਦੇ ਹਨ?',
  'How is my privacy protected?' => 'ਮੇਰੀ ਗੋਪਨੀਯਤਾ ਕਿਵੇਂ ਸੁਰੱਖਿਅਤ ਹੈ?',
  'How many upload languages are available?' => 'ਕਿੰਨੀਆਂ ਅਪਲੋਡ ਭਾਸ਼ਾਵਾਂ ਉਪਲਬਧ ਹਨ?',
  'How PlayHub uses cookies and browser storage for sessions, security, preferences, and playback.' => 'PlayHub ਸੈਸ਼ਨਾਂ, ਸੁਰੱਖਿਆ, ਤਰਜੀਹਾਂ, ਅਤੇ ਪਲੇਬੈਕ ਲਈ ਕੂਕੀਜ਼ ਅਤੇ ਬ੍ਰਾਊਜ਼ਰ ਸਟੋਰੇਜ ਦੀ ਵਰਤੋਂ ਕਿਵੇਂ ਕਰਦਾ ਹੈ।',
  'How this PlayHub deployment handles account, content, activity, security, and preference data.' => 'ਇਹ PlayHub ਤੈਨਾਤੀ ਖਾਤੇ, ਸਮੱਗਰੀ, ਗਤੀਵਿਧੀ, ਸੁਰੱਖਿਆ, ਅਤੇ ਤਰਜੀਹ ਡੇਟਾ ਨੂੰ ਕਿਵੇਂ ਸੰਭਾਲਦੀ ਹੈ।',
  'How to upload your first video' => 'ਆਪਣਾ ਪਹਿਲਾ ਵੀਡੀਓ ਕਿਵੇਂ ਅਪਲੋਡ ਕਰਨਾ ਹੈ',
  'I need help with my account' => 'ਮੈਨੂੰ ਮੇਰੇ ਖਾਤੇ ਵਿੱਚ ਮਦਦ ਦੀ ਲੋੜ ਹੈ',
  'icon-button mini-icon' => 'ਆਈਕਨ-ਬਟਨ ਮਿੰਨੀ-ਆਈਕਨ',
  'If approved, payment is returned through the original method.' => 'ਜੇਕਰ ਮਨਜ਼ੂਰੀ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ, ਤਾਂ ਭੁਗਤਾਨ ਅਸਲ ਵਿਧੀ ਰਾਹੀਂ ਵਾਪਸ ਕਰ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ।',
  'If no paid transaction exists in the connected billing provider or platform records, there is no platform charge to refund. Refunds can only be reviewed against payment records, subscription IDs, invoices, or transaction references.' => 'ਜੇਕਰ ਕਨੈਕਟ ਕੀਤੇ ਬਿਲਿੰਗ ਪ੍ਰਦਾਤਾ ਜਾਂ ਪਲੇਟਫਾਰਮ ਰਿਕਾਰਡਾਂ ਵਿੱਚ ਕੋਈ ਭੁਗਤਾਨ ਕੀਤਾ ਲੈਣ-ਦੇਣ ਮੌਜੂਦ ਨਹੀਂ ਹੈ, ਤਾਂ ਰਿਫੰਡ ਲਈ ਕੋਈ ਪਲੇਟਫਾਰਮ ਚਾਰਜ ਨਹੀਂ ਹੈ। ਰਿਫੰਡ ਦੀ ਸਮੀਖਿਆ ਸਿਰਫ ਅਸਲ ਭੁਗਤਾਨ ਰਿਕਾਰਡਾਂ, ਗਾਹਕੀ ਆਈਡੀ, ਇਨਵੌਇਸ, ਜਾਂ ਲੈਣ-ਦੇਣ ਸੰਦਰਭਾਂ ਦੇ ਵਿਰੁੱਧ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ।',
  'Integration rules' => 'ਏਕੀਕਰਣ ਨਿਯਮ',
  'Join the future of video' => 'ਵੀਡੀਓ ਦੇ ਭਵਿੱਖ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਵੋ',
  'Keeps queue and watch progress on this device.' => 'ਕਤਾਰ ਬਣਾਈ ਰੱਖਦਾ ਹੈ ਅਤੇ ਇਸ ਡਿਵਾਈਸ \'ਤੇ ਪ੍ਰਗਤੀ ਨੂੰ ਦੇਖਦਾ ਹੈ।',
  'Playback Queue' => 'Playback Queue',
  'Keeps your temporary playback queue on this device.' => 'Keeps your temporary playback queue on this device.',
  'Watch Progress' => 'Watch Progress',
  'Saves continue-watching progress for signed-in users.' => 'Saves continue-watching progress for signed-in users.',
  'video_watch_progress' => 'video_watch_progress',
  'Languages' => 'ਭਾਸ਼ਾਵਾਂ',
  'Large uploads use upload sessions: create a session, send numbered chunks, then complete the session with title, description, category, language, visibility, schedule, thumbnail, captions, and monetization fields.' => 'ਵੱਡੇ ਅੱਪਲੋਡ ਅੱਪਲੋਡ ਸੈਸ਼ਨਾਂ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹਨ: ਇੱਕ ਸੈਸ਼ਨ ਬਣਾਓ, ਨੰਬਰ ਵਾਲੇ ਹਿੱਸੇ ਭੇਜੋ, ਫਿਰ ਸਿਰਲੇਖ, ਵਰਣਨ, ਸ਼੍ਰੇਣੀ, ਭਾਸ਼ਾ, ਦਿੱਖ, ਸਮਾਂ-ਸਾਰਣੀ, ਥੰਬਨੇਲ, ਸੁਰਖੀਆਂ, ਅਤੇ ਮੁਦਰੀਕਰਨ ਖੇਤਰਾਂ ਦੇ ਨਾਲ ਸੈਸ਼ਨ ਨੂੰ ਪੂਰਾ ਕਰੋ।',
  'Last updated: June 29, 2026' => 'ਆਖਰੀ ਵਾਰ ਅੱਪਡੇਟ ਕੀਤਾ: 29 ਜੂਨ, 2026',
