  'Loading category activity...' => 'ਸ਼੍ਰੇਣੀ ਗਤੀਵਿਧੀ ਲੋਡ ਕੀਤੀ ਜਾ ਰਹੀ ਹੈ...',
  'Loading creator and content counts.' => 'ਸਿਰਜਣਹਾਰ ਅਤੇ ਸਮੱਗਰੀ ਦੀ ਗਿਣਤੀ ਲੋਡ ਕੀਤੀ ਜਾ ਰਹੀ ਹੈ।',
  'Loading creator channels...' => 'ਡੇਟਾਬੇਸ ਤੋਂ ਸਿਰਜਣਹਾਰ ਚੈਨਲ ਲੋਡ ਕੀਤੇ ਜਾ ਰਹੇ ਹਨ...',
  'Loading endpoints' => 'ਅੰਤਮ ਬਿੰਦੂ ਲੋਡ ਕੀਤੇ ਜਾ ਰਹੇ ਹਨ',
