  'Loading live API metadata...' => 'ਲਾਈਵ API ਮੈਟਾਡੇਟਾ ਲੋਡ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ...',
  'Loading live PlayHub platform data from the backend...' => 'ਬੈਕਐਂਡ ਤੋਂ ਲਾਈਵ PlayHub ਪਲੇਟਫਾਰਮ ਡਾਟਾ ਲੋਡ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ...',
