  'Loading taxonomy metadata.' => 'ਵਰਗੀਕਰਨ ਮੈਟਾਡੇਟਾ ਲੋਡ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ।',
  'Loading upload configuration.' => 'ਅੱਪਲੋਡ ਸੰਰੂਪਣ ਲੋਡ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ।',
  'Loading...' => 'ਲੋਡ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ...',
