  'Manage language, theme, security, and notification settings from your account.' => 'ਆਪਣੇ ਖਾਤੇ ਤੋਂ ਭਾਸ਼ਾ, ਥੀਮ, ਸੁਰੱਖਿਆ ਅਤੇ ਸੂਚਨਾ ਸੈਟਿੰਗਾਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰੋ।',
  'Max upload' => 'ਅਧਿਕਤਮ ਅੱਪਲੋਡ',
  'Media and analytics storage' => 'ਮੀਡੀਆ ਅਤੇ ਵਿਸ਼ਲੇਸ਼ਣ ਸਟੋਰੇਜ',
  'Messages submitted on the Contact page are saved and shown in the admin Support dashboard as contact tickets.' => 'ਸੰਪਰਕ ਪੰਨੇ \'ਤੇ ਜਮ੍ਹਾਂ ਕੀਤੇ ਸੰਦੇਸ਼ਾਂ ਨੂੰ ਡੇਟਾਬੇਸ ਵਿੱਚ ਸਟੋਰ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਸੰਪਰਕ ਟਿਕਟਾਂ ਦੇ ਰੂਪ ਵਿੱਚ ਐਡਮਿਨ ਸਪੋਰਟ ਡੈਸ਼ਬੋਰਡ ਵਿੱਚ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ।',
  'Moderation help' => 'ਸੰਜਮ ਮਦਦ',
  'More⌄' => 'ਹੋਰ⌄',
  'Need help?' => 'ਮਦਦ ਦੀ ਲੋੜ ਹੈ?',
  'Need more help?' => 'ਹੋਰ ਮਦਦ ਦੀ ਲੋੜ ਹੈ?',
  'No answers found for this topic and search.' => 'ਇਸ ਵਿਸ਼ੇ ਅਤੇ ਖੋਜ ਲਈ ਕੋਈ ਜਵਾਬ ਨਹੀਂ ਮਿਲੇ।',
  'No category activity found yet.' => 'ਅਜੇ ਤੱਕ ਕੋਈ ਸ਼੍ਰੇਣੀ ਗਤੀਵਿਧੀ ਨਹੀਂ ਮਿਲੀ।',
  'No creator channels found yet.' => 'ਅਜੇ ਤੱਕ ਕੋਈ ਸਿਰਜਣਹਾਰ ਚੈਨਲ ਨਹੀਂ ਮਿਲੇ ਹਨ।',
  'No upload categories are configured.' => 'ਕੋਈ ਅੱਪਲੋਡ ਸ਼੍ਰੇਣੀਆਂ ਕੌਂਫਿਗਰ ਨਹੀਂ ਕੀਤੀਆਂ ਗਈਆਂ ਹਨ।',
  'Non-refundable cases' => 'ਨਾ-ਵਾਪਸੀਯੋਗ ਕੇਸ',
  'noopener,noreferrer' => 'noopener, noreferr',
  'Normal priority' => 'ਸਧਾਰਣ ਤਰਜੀਹ',
  'Not available' => 'ਉਪਲਬਧ ਨਹੀਂ ਹੈ',
  'Not provided' => 'ਪ੍ਰਦਾਨ ਨਹੀਂ ਕੀਤੀ ਗਈ',
  'Official contact addresses, billing contacts, and external support channels should be configured by the PlayHub site administrator for this deployment. This page intentionally does not display unverified email addresses.' => 'ਅਧਿਕਾਰਤ ਸੰਪਰਕ ਪਤੇ, ਬਿਲਿੰਗ ਸੰਪਰਕ, ਅਤੇ ਬਾਹਰੀ ਸਹਾਇਤਾ ਚੈਨਲਾਂ ਨੂੰ ਇਸ ਤੈਨਾਤੀ ਲਈ PlayHub ਸਾਈਟ ਪ੍ਰਸ਼ਾਸਕ ਦੁਆਰਾ ਕੌਂਫਿਗਰ ਕੀਤਾ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ। ਇਹ ਪੰਨਾ ਜਾਣਬੁੱਝ ਕੇ ਅਣ-ਪ੍ਰਮਾਣਿਤ ਈਮੇਲ ਪਤੇ ਪ੍ਰਦਰਸ਼ਿਤ ਨਹੀਂ ਕਰਦਾ ਹੈ।',
  'On this page' => 'ਇਸ ਪੰਨੇ \'ਤੇ',
  'Open Help Center' => 'ਮਦਦ ਕੇਂਦਰ ਖੋਲ੍ਹੋ',
  'Open settings' => 'ਸੈਟਿੰਗਾਂ ਖੋਲ੍ਹੋ',
  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'ਸੈਟਿੰਗਾਂ ਖੋਲ੍ਹੋ, ਸੁਰੱਖਿਆ \'ਤੇ ਜਾਓ, ਫਿਰ ਪਾਸਵਰਡ ਜਾਂ ਦੋ-ਕਾਰਕ ਡਾਇਲਾਗ ਦੀ ਵਰਤੋਂ ਕਰੋ। ਕੌਂਫਿਗਰ ਹੋਣ \'ਤੇ ਦੋ-ਫੈਕਟਰ ਡਿਲੀਵਰੀ ਈਮੇਲ ਜਾਂ ਫ਼ੋਨ ਦਾ ਸਮਰਥਨ ਕਰਦੀ ਹੈ।',
  'Operational snapshot' => 'ਕਾਰਜਸ਼ੀਲ ਸਨੈਪਸ਼ਾਟ',
  'Optional, but recommended' => 'ਵਿਕਲਪਿਕ, ਪਰ ਸਿਫ਼ਾਰਿਸ਼ ਕੀਤੀ',
  'Other' => 'ਹੋਰ',
  'Partnerships, press, and platform operations.' => 'ਭਾਈਵਾਲੀ, ਪ੍ਰੈਸ, ਅਤੇ ਪਲੇਟਫਾਰਮ ਓਪਰੇਸ਼ਨ।',
  'Payment help' => 'ਭੁਗਤਾਨ ਮਦਦ',
  'Platform' => 'ਪਲੇਟਫਾਰਮ',
  'Playback' => 'ਪਲੇਬੈਕ',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'ਪਲੇਬੈਕ ਪ੍ਰਗਤੀ, ਬਾਅਦ ਵਿੱਚ ਦੇਖਣ ਦੀ ਸਥਿਤੀ, ਪਸੰਦਾਂ, ਟਿੱਪਣੀਆਂ, ਗਾਹਕੀਆਂ, ਸੂਚਨਾਵਾਂ, ਅਤੇ ਐਡਮਿਨ ਵਿਸ਼ਲੇਸ਼ਣ ਡੇਟਾਬੇਸ ਵਿੱਚ ਸਟੋਰ ਕੀਤੇ ਜਾਂਦੇ ਹਨ ਜਦੋਂ ਪ੍ਰਮਾਣਿਤ ਪਲੇਟਫਾਰਮ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਨਾਲ ਲਿੰਕ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'ਪਲੇਬੈਕ, ਟਿੱਪਣੀਆਂ, ਪਸੰਦਾਂ, ਬਾਅਦ ਵਿੱਚ ਦੇਖੋ, ਗਾਹਕੀ, ਸੂਚਨਾਵਾਂ, ਸੁਨੇਹੇ, ਪਲੇਲਿਸਟਸ, ਅਤੇ ਭਾਸ਼ਾ ਸੈਟਿੰਗਾਂ ਮੁੱਖ ਨੈਵੀਗੇਸ਼ਨ ਅਤੇ ਖਾਤਾ ਮੀਨੂ ਰਾਹੀਂ ਉਪਲਬਧ ਹਨ।',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub ਇੱਕ ਖਾਤੇ ਤੋਂ ਸਿਰਜਣਹਾਰ ਸਮੱਗਰੀ ਨੂੰ ਅੱਪਲੋਡ ਕਰਨ, ਦੇਖਣ, ਸਮਾਂ-ਸਾਰਣੀ, ਪ੍ਰਬੰਧਨ ਅਤੇ ਸੰਚਾਲਨ ਕਰਨ ਲਈ ਇੱਕ ਵੀਡੀਓ ਪਲੇਟਫਾਰਮ ਹੈ।',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub ਇਸ ਤੈਨਾਤੀ \'ਤੇ ਚੱਲ ਰਿਹਾ ਵੀਡੀਓ ਪਲੇਟਫਾਰਮ ਹੈ, ਜੋ ਸਿਰਜਣਹਾਰਾਂ, ਦਰਸ਼ਕਾਂ, ਭਾਈਚਾਰਿਆਂ ਅਤੇ ਪਲੇਟਫਾਰਮ ਆਪਰੇਟਰਾਂ ਲਈ ਬਣਾਇਆ ਗਿਆ ਹੈ।',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub ਇੱਕ ਪਲੇਟਫਾਰਮ ਤੋਂ ਸਿਰਜਣਹਾਰ ਚੈਨਲ, ਵੀਡੀਓ ਅੱਪਲੋਡ, ਅਨੁਸੂਚਿਤ ਪ੍ਰਕਾਸ਼ਨ, ਗਾਹਕੀ, ਟਿੱਪਣੀਆਂ, ਪਲੇਲਿਸਟਸ, ਬਾਅਦ ਵਿੱਚ ਦੇਖੋ, ਲਾਈਵ ਸਮੱਗਰੀ ਪੰਨੇ, ਅਤੇ ਪ੍ਰਸ਼ਾਸਨ ਟੂਲ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ।',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub ਲੌਗਇਨ ਸੈਸ਼ਨਾਂ, API ਪ੍ਰਮਾਣਿਕਤਾ, CSRF/ਸੁਰੱਖਿਆ ਵਿਹਾਰ, ਭਾਸ਼ਾ ਦੀ ਚੋਣ, ਥੀਮ ਦੀ ਚੋਣ, ਖਾਤਾ ਮੀਨੂ ਸਥਿਤੀ, ਅਤੇ ਐਪਲੀਕੇਸ਼ਨ ਦੇ ਕੰਮ ਕਰਨ ਲਈ ਲੋੜੀਂਦੀਆਂ ਹੋਰ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਲਈ ਜ਼ਰੂਰੀ ਕੂਕੀਜ਼ ਅਤੇ ਬ੍ਰਾਊਜ਼ਰ ਸਟੋਰੇਜ ਦੀ ਵਰਤੋਂ ਕਰਦਾ ਹੈ।',
  'playhub_language, theme' => 'playhub_language, ਥੀਮ',
  'Popular questions' => 'ਪ੍ਰਸਿੱਧ ਸਵਾਲ',
  'Preference storage' => 'ਤਰਜੀਹ ਸਟੋਰੇਜ਼',
  'Privacy Policy' => 'ਗੋਪਨੀਯਤਾ ਨੀਤੀ',
  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'ਗੋਪਨੀਯਤਾ, ਕੂਕੀਜ਼, ਖਾਤਾ ਸੁਰੱਖਿਆ, ਸਹਾਇਤਾ ਸੁਨੇਹੇ, ਅਤੇ ਸੰਚਾਲਨ ਡੇਟਾ ਨੂੰ PlayHub ਨਾਲ ਜੁੜੀਆਂ ਨੀਤੀਆਂ ਅਤੇ ਬੈਕਐਂਡ ਰਿਕਾਰਡਾਂ ਦੁਆਰਾ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ।',
  'Profile, login, security, and settings help.' => 'ਪ੍ਰੋਫਾਈਲ, ਲੌਗਇਨ, ਸੁਰੱਖਿਆ ਅਤੇ ਸੈਟਿੰਗਾਂ ਮਦਦ।',
  'Profile, security, and preferences.' => 'ਪ੍ਰੋਫਾਈਲ, ਸੁਰੱਖਿਆ ਅਤੇ ਤਰਜੀਹਾਂ।',
  'Public API route' => 'ਜਨਤਕ API ਰੂਟ',
  'Public JSON endpoints include /api/health for deployment status and /api/upload-options for upload categories, languages, limits, chunk size, and trending tags.' => 'ਜਨਤਕ JSON ਅੰਤਮ ਬਿੰਦੂਆਂ ਵਿੱਚ ਤੈਨਾਤੀ ਸਥਿਤੀ ਲਈ /api/ਸਿਹਤ ਅਤੇ ਅੱਪਲੋਡ ਸ਼੍ਰੇਣੀਆਂ, ਭਾਸ਼ਾਵਾਂ, ਸੀਮਾਵਾਂ, ਭਾਗ ਦਾ ਆਕਾਰ, ਅਤੇ ਰੁਝਾਨ ਵਾਲੇ ਟੈਗ ਲਈ /api/upload-options ਸ਼ਾਮਲ ਹਨ।',
