  'Refund handling for paid PlayHub features depends on billing records attached to this deployment.' => 'ਭੁਗਤਾਨ ਕੀਤੀ PlayHub ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਲਈ ਰਿਫੰਡ ਹੈਂਡਲਿੰਗ ਇਸ ਤੈਨਾਤੀ ਨਾਲ ਜੁੜੇ ਅਸਲ ਬਿਲਿੰਗ ਰਿਕਾਰਡਾਂ \'ਤੇ ਨਿਰਭਰ ਕਰਦੀ ਹੈ।',
  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'ਰਿਫੰਡ ਹੈਂਡਲਿੰਗ ਅਸਲ ਬਿਲਿੰਗ ਰਿਕਾਰਡ ਅਤੇ ਪ੍ਰਸ਼ਾਸਕ ਸਮੀਖਿਆ ਨਾਲ ਜੁੜੀ ਹੋਈ ਹੈ। ਜੇਕਰ ਬਿਲਿੰਗ ਇਸ ਤੈਨਾਤੀ ਲਈ ਕੌਂਫਿਗਰ ਨਹੀਂ ਕੀਤੀ ਗਈ ਹੈ, ਤਾਂ ਰਿਫੰਡ ਲਈ ਕੋਈ ਪਲੇਟਫਾਰਮ ਚਾਰਜ ਨਹੀਂ ਹੈ।',
