  'Search for answers...' => 'ਜਵਾਬਾਂ ਦੀ ਖੋਜ ਕਰੋ...',
  'Search help articles, topics, or questions...' => 'ਮਦਦ ਲੇਖ, ਵਿਸ਼ੇ, ਜਾਂ ਸਵਾਲ ਖੋਜੋ...',
  'Select a reason' => 'ਇੱਕ ਕਾਰਨ ਚੁਣੋ',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'ਇੱਕ ਜਾਂ ਇੱਕ ਤੋਂ ਵੱਧ ਵੀਡੀਓ ਫਾਈਲਾਂ ਚੁਣੋ, ਲੋੜੀਂਦੇ ਵੇਰਵੇ ਦਰਜ ਕਰੋ, ਸ਼੍ਰੇਣੀ ਅਤੇ ਭਾਸ਼ਾ ਚੁਣੋ, ਥੰਬਨੇਲ ਸ਼ਾਮਲ ਕਰੋ, ਦਿੱਖ ਦੀ ਚੋਣ ਕਰੋ ਅਤੇ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰੋ। ਸਰਵਰ ਦੁਆਰਾ ਪ੍ਰਕਿਰਿਆ ਸ਼ੁਰੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਵੱਡੀਆਂ ਫਾਈਲਾਂ ਨੂੰ ਟੁਕੜਿਆਂ ਵਿੱਚ ਅੱਪਲੋਡ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।',
  'Send a message and it will be saved for admins.' => 'ਇੱਕ ਸੁਨੇਹਾ ਭੇਜੋ ਅਤੇ ਇਹ ਪ੍ਰਬੰਧਕਾਂ ਲਈ ਸੁਰੱਖਿਅਤ ਹੋ ਜਾਵੇਗਾ।',
  'Send billing details to admin support for review.' => 'ਸਮੀਖਿਆ ਲਈ ਪ੍ਰਸ਼ਾਸਕ ਸਹਾਇਤਾ ਨੂੰ ਬਿਲਿੰਗ ਵੇਰਵੇ ਭੇਜੋ।',
  'Send message' => 'ਸੁਨੇਹਾ ਭੇਜੋ',
