  'The configured' => 'ਸੰਰਚਿਤ',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'ਡਿਵੈਲਪਰ ਪੰਨਾ ਲਾਈਵ ਲਾਰਵੇਲ ਬੈਕਐਂਡ ਨਾਲ ਜੁੜਿਆ ਹੋਇਆ ਹੈ: ਰੂਟ ਵਸਤੂ ਸੂਚੀ, ਡੇਟਾਬੇਸ ਗਿਣਤੀ, ਅਪਲੋਡ ਸੀਮਾਵਾਂ, ਅਤੇ ਪਲੇਟਫਾਰਮ ਮੈਟਾਡੇਟਾ /api/developers ਤੋਂ ਲੋਡ ਕੀਤੇ ਜਾਂਦੇ ਹਨ।',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'ਫਰੰਟਐਂਡ ਤਰਜੀਹਾਂ ਨੂੰ ਸਟੋਰ ਕਰਦਾ ਹੈ ਜਿਵੇਂ ਕਿ ਚੁਣੀ ਗਈ ਭਾਸ਼ਾ, ਥੀਮ, ਪਲੇਬੈਕ ਕਤਾਰ, ਦੇਖਣ ਦੀ ਪ੍ਰਗਤੀ, ਅਤੇ ਇੰਟਰਫੇਸ ਸਥਿਤੀ ਤਾਂ ਕਿ ਅਨੁਭਵ ਪੰਨਾ ਨੈਵੀਗੇਸ਼ਨ ਅਤੇ ਰੀਲੋਡਸ ਵਿੱਚ ਇਕਸਾਰ ਰਹੇ।',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'ਪ੍ਰੋਸੈਸਿੰਗ ਜੌਬ ਪੇਸ਼ਕਾਰੀ ਨੂੰ ਏਨਕੋਡ ਕਰਦੀ ਹੈ, ਲੋੜ ਪੈਣ \'ਤੇ ਥੰਬਨੇਲ ਬਣਾਉਂਦੀ ਹੈ, ਸੁਰਖੀਆਂ ਨੂੰ ਸਟੋਰ ਕਰਦੀ ਹੈ, ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਪੂਰੀ ਹੋਣ \'ਤੇ ਵੀਡੀਓਜ਼ ਨੂੰ ਤਿਆਰ ਕਰਦੀ ਹੈ। ਭਵਿੱਖ ਦੇ ਨਿਯਤ ਕੀਤੇ ਵੀਡੀਓ ਉਦੋਂ ਤੱਕ ਨਿੱਜੀ ਰਹਿੰਦੇ ਹਨ ਜਦੋਂ ਤੱਕ ਸ਼ਡਿਊਲਰ ਉਹਨਾਂ ਨੂੰ ਜਾਰੀ ਨਹੀਂ ਕਰਦਾ।',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'ਅਪਲੋਡ ਸਿਸਟਮ ਡੇਟਾਬੇਸ-ਬੈਕਡ ਹੈ, API ਤੋਂ ਸ਼੍ਰੇਣੀਆਂ ਅਤੇ ਭਾਸ਼ਾਵਾਂ ਦਾ ਸਮਰਥਨ ਕਰਦਾ ਹੈ, ਅਪਲੋਡ ਕੀਤੇ ਵੀਡੀਓਜ਼ ਦੀ ਪ੍ਰਕਿਰਿਆ ਕਰਦਾ ਹੈ, ਥੰਬਨੇਲ ਅਤੇ ਸੁਰਖੀਆਂ ਨੂੰ ਸਟੋਰ ਕਰਦਾ ਹੈ, ਅਤੇ ਅਨੁਸੂਚਿਤ ਸਮਗਰੀ ਨੂੰ ਇਸਦੇ ਰਿਲੀਜ਼ ਸਮੇਂ ਤੱਕ ਨਿਜੀ ਰੱਖਦਾ ਹੈ।',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'ਇਹ ਪੰਨਾ ਦੱਸਦਾ ਹੈ ਕਿ ਕਿਵੇਂ PlayHub ਸੈਸ਼ਨਾਂ, ਸੁਰੱਖਿਆ, ਤਰਜੀਹਾਂ, ਪਲੇਬੈਕ, ਅਤੇ ਪ੍ਰਮਾਣਿਤ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਲਈ ਕੂਕੀਜ਼ ਅਤੇ ਬ੍ਰਾਊਜ਼ਰ ਸਟੋਰੇਜ ਦੀ ਵਰਤੋਂ ਕਰਦਾ ਹੈ।',
  'Ticket source' => 'ਟਿਕਟ ਸਰੋਤ',
  'Top content categories' => 'ਪ੍ਰਮੁੱਖ ਸਮੱਗਰੀ ਸ਼੍ਰੇਣੀਆਂ',
  'Topic' => 'ਵਿਸ਼ਾ',
  'Transaction / invoice' => 'ਲੈਣ-ਦੇਣ / ਚਲਾਨ',
  'Transaction / invoice ID' => 'ਟ੍ਰਾਂਜੈਕਸ਼ਨ / ਇਨਵੌਇਸ ਆਈ.ਡੀ',
  'Unable to send message.' => 'ਸੁਨੇਹਾ ਭੇਜਣ ਵਿੱਚ ਅਸਮਰੱਥ।',
  'Unable to submit refund request.' => 'ਰਿਫੰਡ ਦੀ ਬੇਨਤੀ ਸਪੁਰਦ ਕਰਨ ਵਿੱਚ ਅਸਮਰੱਥ।',
  'Understanding admin support tickets' => 'ਐਡਮਿਨ ਸਹਾਇਤਾ ਟਿਕਟਾਂ ਨੂੰ ਸਮਝਣਾ',
  'Upload and processing help' => 'ਅੱਪਲੋਡ ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਮਦਦ',
  'Upload chunks' => 'ਭਾਗ ਅੱਪਲੋਡ ਕਰੋ',
  'Upload issues' => 'ਅੱਪਲੋਡ ਮੁੱਦੇ',
  'Upload languages' => 'ਭਾਸ਼ਾਵਾਂ ਅੱਪਲੋਡ ਕਰੋ',
  'Upload limit' => 'ਅੱਪਲੋਡ ਸੀਮਾ',
  'Upload options' => 'ਅੱਪਲੋਡ ਵਿਕਲਪ',
  'Upload or processing' => 'ਅੱਪਲੋਡ ਜਾਂ ਪ੍ਰੋਸੈਸਿੰਗ',
  'Upload page' => 'ਅੱਪਲੋਡ ਪੰਨਾ',
  'Upload pipeline' => 'ਪਾਈਪਲਾਈਨ ਅੱਪਲੋਡ ਕਰੋ',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'ਲਾਈਵ PlayHub ਡੇਟਾ ਨਾਲ ਅੱਪਲੋਡ ਕਰੋ, ਦੇਖੋ, ਗਾਹਕ ਬਣੋ, ਸੰਚਾਲਿਤ ਕਰੋ ਅਤੇ ਬਿਲਡ ਕਰੋ।',
  'Uploaded videos' => 'ਅੱਪਲੋਡ ਕੀਤੇ ਵੀਡੀਓ',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'ਅਪਲੋਡ ਕੀਤੇ ਵੀਡੀਓਜ਼ ਨੂੰ ਚਲਾਉਣਯੋਗ ਪੇਸ਼ਕਾਰੀ ਵਿੱਚ ਏਨਕੋਡ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਪ੍ਰੋਸੈਸਿੰਗ ਸਮਾਂ ਫਾਈਲ ਦੇ ਆਕਾਰ, ਮਿਆਦ, ਸਰਵਰ ਲੋਡ ਅਤੇ ਕਤਾਰ ਸਥਿਤੀ \'ਤੇ ਨਿਰਭਰ ਕਰਦਾ ਹੈ। ਅੱਪਲੋਡ ਪੰਨਾ ਅਤੇ ਸਿਰਜਣਹਾਰ ਸਟੂਡੀਓ ਵੀਡੀਓ ਰਿਕਾਰਡ ਤੋਂ ਅਸਲ ਪ੍ਰੋਸੈਸਿੰਗ ਸਥਿਤੀ ਦਿਖਾਉਂਦੇ ਹਨ।',
  'Uploads, scheduling, and processing are available.' => 'ਅੱਪਲੋਡ, ਸਮਾਂ-ਸਾਰਣੀ ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਉਪਲਬਧ ਹਨ।',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'ਸਿਰਜਣਹਾਰ ਵਰਕਫਲੋ ਲਈ /api/ਵੀਡੀਓ, ਚੈਨਲ ਐਂਡਪੁਆਇੰਟ, ਅਤੇ ਪ੍ਰਮਾਣਿਤ ਰੂਟਾਂ ਦੀ ਵਰਤੋਂ ਕਰੋ।',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'ਵੀਡੀਓ ਅਤੇ ਟਿੱਪਣੀਆਂ ਲਈ ਬਿਲਟ-ਇਨ ਰਿਪੋਰਟ ਕਾਰਵਾਈਆਂ ਦੀ ਵਰਤੋਂ ਕਰੋ ਤਾਂ ਜੋ ਪ੍ਰਸ਼ਾਸਕਾਂ ਨੂੰ ਸਮੱਗਰੀ ਦਾ ਸਹੀ ਹਵਾਲਾ ਪ੍ਰਾਪਤ ਹੋਵੇ। ਐਡਮਿਨ ਡੈਸ਼ਬੋਰਡ ਪੰਨੇ ਉਪਭੋਗਤਾਵਾਂ, ਸਮੱਗਰੀ, ਰਿਪੋਰਟਾਂ, ਮੁਦਰੀਕਰਨ, ਵਿਸ਼ਲੇਸ਼ਣ, ਸਮਰਥਨ, ਭੂਮਿਕਾਵਾਂ ਅਤੇ ਸਿਸਟਮ ਸੈਟਿੰਗਾਂ ਲਈ ਲਾਈਵ ਡੇਟਾਬੇਸ ਡੇਟਾ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹਨ।',
  'Use Contact Us' => 'ਸਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੋ ਦੀ ਵਰਤੋਂ ਕਰੋ',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'ਆਮ API ਬੇਨਤੀਆਂ ਲਈ JSON ਅਤੇ ਫਾਈਲ ਅਪਲੋਡ ਕਰਨ ਲਈ ਫਾਰਮਡਾਟਾ ਦੀ ਵਰਤੋਂ ਕਰੋ। ਪ੍ਰਮਾਣਿਕਤਾ ਨੂੰ ਬਾਈਪਾਸ ਨਾ ਕਰੋ: ਸ਼੍ਰੇਣੀਆਂ ਅਤੇ ਭਾਸ਼ਾਵਾਂ ਡੇਟਾਬੇਸ ਆਈਡੀ ਹਨ, ਦਿੱਖ ਜਨਤਕ, ਗੈਰ-ਸੂਚੀਬੱਧ, ਜਾਂ ਨਿੱਜੀ ਤੱਕ ਸੀਮਿਤ ਹੈ, ਅਤੇ ਸੁਰਖੀਆਂ SRT, VTT, ਜਾਂ TXT ਫਾਈਲਾਂ ਨੂੰ ਸਵੀਕਾਰ ਕਰਦੀਆਂ ਹਨ।',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'ਆਪਣੀ ਪ੍ਰੋਫਾਈਲ, ਸੁਰੱਖਿਆ, ਪਾਸਵਰਡ, ਦੋ-ਫੈਕਟਰ ਡਿਲੀਵਰੀ, ਡਿਵਾਈਸਾਂ, ਤਰਜੀਹਾਂ ਅਤੇ ਸੂਚਨਾ ਵਿਕਲਪਾਂ ਨੂੰ ਅਪਡੇਟ ਕਰਨ ਲਈ ਸੈਟਿੰਗਾਂ ਦੀ ਵਰਤੋਂ ਕਰੋ। ਜੇਕਰ ਤੁਸੀਂ ਆਪਣੇ ਖਾਤੇ ਤੱਕ ਨਹੀਂ ਪਹੁੰਚ ਸਕਦੇ ਹੋ, ਤਾਂ ਲੌਗਇਨ ਪ੍ਰਵਾਹ ਦੀ ਵਰਤੋਂ ਕਰੋ ਅਤੇ ਸਾਈਟ ਪ੍ਰਸ਼ਾਸਕ ਨੂੰ ਖਾਤਾ ਈਮੇਲ ਪ੍ਰਦਾਨ ਕਰੋ।',
  'Use the contact form' => 'ਸੰਪਰਕ ਫਾਰਮ ਦੀ ਵਰਤੋਂ ਕਰੋ',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'ਵੀਡੀਓ, ਟਿੱਪਣੀਆਂ ਅਤੇ ਕਮਿਊਨਿਟੀ ਪੋਸਟਾਂ \'ਤੇ ਰਿਪੋਰਟ ਕਾਰਵਾਈਆਂ ਦੀ ਵਰਤੋਂ ਕਰੋ ਤਾਂ ਜੋ ਪ੍ਰਸ਼ਾਸਕਾਂ ਨੂੰ ਸਮੱਗਰੀ ਦਾ ਸਹੀ ਹਵਾਲਾ ਮਿਲੇ।',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'ਜਦੋਂ ਸਮੱਗਰੀ ਪਲੇਟਫਾਰਮ ਨਿਯਮਾਂ ਦੀ ਉਲੰਘਣਾ ਕਰ ਸਕਦੀ ਹੈ ਤਾਂ ਵੀਡੀਓ, ਟਿੱਪਣੀਆਂ ਅਤੇ ਕਮਿਊਨਿਟੀ ਪੋਸਟਾਂ \'ਤੇ ਰਿਪੋਰਟ ਕਾਰਵਾਈਆਂ ਦੀ ਵਰਤੋਂ ਕਰੋ। ਇਹ ਰਿਪੋਰਟਾਂ ਅਸਲ ਸਮੱਗਰੀ ਰਿਕਾਰਡ ਨਾਲ ਜੁੜੀਆਂ ਹੋਈਆਂ ਹਨ ਅਤੇ ਇੱਕ ਆਮ ਸੰਦੇਸ਼ ਨਾਲੋਂ ਬਿਹਤਰ ਹਨ ਕਿਉਂਕਿ ਪ੍ਰਸ਼ਾਸਕ ਸਹੀ ਆਈਟਮ ਦੀ ਸਮੀਖਿਆ ਕਰ ਸਕਦੇ ਹਨ।',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'ਖਾਤਾ ਮਦਦ, ਸਮੱਗਰੀ ਰਿਪੋਰਟਾਂ, ਤਕਨੀਕੀ ਸਮੱਸਿਆਵਾਂ, ਅਤੇ ਪ੍ਰਬੰਧਕ ਬੇਨਤੀਆਂ ਲਈ ਸਹੀ PlayHub ਚੈਨਲ ਦੀ ਵਰਤੋਂ ਕਰੋ।',
  'Video categories' => 'ਵੀਡੀਓ ਸ਼੍ਰੇਣੀਆਂ',
  'Video for everyone. Built for creators and viewers.' => 'ਹਰ ਕਿਸੇ ਲਈ ਵੀਡੀਓ. ਅਸਲ ਪਲੇਟਫਾਰਮ ਡੇਟਾ ਤੋਂ ਬਣਾਇਆ ਗਿਆ।',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'ਵੀਡੀਓ ਅੱਪਲੋਡ, ਸਮਾਂ-ਸਾਰਣੀ, ਥੰਬਨੇਲ, ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਸਮੱਸਿਆਵਾਂ।',
  'Videos, thumbnails, captions, processing.' => 'ਵੀਡੀਓ, ਥੰਬਨੇਲ, ਸੁਰਖੀਆਂ, ਪ੍ਰੋਸੈਸਿੰਗ।',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'ਦਰਸ਼ਕ ਸ਼੍ਰੇਣੀਆਂ ਨੂੰ ਬ੍ਰਾਊਜ਼ ਕਰ ਸਕਦੇ ਹਨ, ਵੀਡੀਓ ਖੋਜ ਸਕਦੇ ਹਨ, ਸਮੱਗਰੀ ਦੇਖ ਸਕਦੇ ਹਨ, ਚੈਨਲਾਂ ਦੇ ਗਾਹਕ ਬਣ ਸਕਦੇ ਹਨ, ਬਾਅਦ ਵਿੱਚ ਦੇਖਣ ਲਈ ਵੀਡੀਓ ਸੁਰੱਖਿਅਤ ਕਰ ਸਕਦੇ ਹਨ, ਟਿੱਪਣੀ ਕਰ ਸਕਦੇ ਹਨ, ਸੂਚਨਾਵਾਂ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦੇ ਹਨ, ਅਤੇ ਭਾਸ਼ਾ ਅਤੇ ਪਹੁੰਚਯੋਗਤਾ ਤਰਜੀਹਾਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰ ਸਕਦੇ ਹਨ।',
  'Viewing and community help' => 'ਦੇਖਣਾ ਅਤੇ ਕਮਿਊਨਿਟੀ ਮਦਦ',
  'Waiting for backend endpoint inventory.' => 'ਬੈਕਐਂਡ ਐਂਡਪੁਆਇੰਟ ਵਸਤੂ ਸੂਚੀ ਦੀ ਉਡੀਕ ਕੀਤੀ ਜਾ ਰਹੀ ਹੈ।',
  'We’re here to help.' => 'ਅਸੀਂ ਮਦਦ ਕਰਨ ਲਈ ਇੱਥੇ ਹਾਂ।',
  'What is PlayHub?' => 'PlayHub ਕੀ ਹੈ?',
  'What PlayHub does' => 'PlayHub ਕੀ ਕਰਦਾ ਹੈ',
  'Where do contact messages go?' => 'ਸੰਪਰਕ ਸੁਨੇਹੇ ਕਿੱਥੇ ਜਾਂਦੇ ਹਨ?',
  'Why is my video still processing?' => 'ਮੇਰਾ ਵੀਡੀਓ ਅਜੇ ਵੀ ਪ੍ਰਕਿਰਿਆ ਕਿਉਂ ਕਰ ਰਿਹਾ ਹੈ?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'ਹਾਂ। ਅੱਪਲੋਡ ਪੰਨੇ \'ਤੇ ਮੂਲ ਅਨੁਸੂਚੀ ਮਿਤੀ ਅਤੇ ਸਮਾਂ ਖੇਤਰ ਦੀ ਵਰਤੋਂ ਕਰੋ। ਬੈਕਐਂਡ ਸ਼ੈਡਿਊਲਡ_ਐਟ ਸਟੋਰ ਕਰਦਾ ਹੈ, ਵੀਡੀਓ ਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਦਾ ਹੈ, ਇਸ ਨੂੰ ਨਿਜੀ ਰੱਖਦਾ ਹੈ ਜਦੋਂ ਕਿ ਮਿਤੀ ਭਵਿੱਖ ਵਿੱਚ ਹੁੰਦੀ ਹੈ, ਅਤੇ ਇਸਨੂੰ ਜਾਰੀ ਕਰਦਾ ਹੈ ਜਦੋਂ ਲਾਰਵੇਲ ਸ਼ਡਿਊਲਰ ਨਿਰਧਾਰਤ ਸਮੇਂ ਤੋਂ ਬਾਅਦ ਚੱਲਦਾ ਹੈ।',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'ਹਾਂ। ਅੱਪਲੋਡ \'ਤੇ ਮੂਲ ਅਨੁਸੂਚੀ ਖੇਤਰ ਦੀ ਵਰਤੋਂ ਕਰੋ। ਬੈਕਐਂਡ ਸ਼ੈਡਿਊਲ_ਐਟ ਸਟੋਰ ਕਰਦਾ ਹੈ ਅਤੇ ਪ੍ਰੋਸੈਸਿੰਗ ਤੋਂ ਬਾਅਦ ਵੀਡੀਓ ਨੂੰ ਜਾਰੀ ਕਰਦਾ ਹੈ ਜਦੋਂ ਸਮਾਂ-ਸਾਰਣੀ ਦਾ ਸਮਾਂ ਪੂਰਾ ਹੋ ਜਾਂਦਾ ਹੈ।',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'ਤੁਸੀਂ ਮਹਿਮਾਨ ਵਜੋਂ ਬ੍ਰਾਊਜ਼ ਕਰ ਰਹੇ ਹੋ। ਖਾਤਾ-ਵਿਸ਼ੇਸ਼ ਟੂਲਸ ਤੱਕ ਪਹੁੰਚ ਕਰਨ ਲਈ ਸਾਈਨ ਇਨ ਕਰੋ।',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'ਤੁਸੀਂ ਆਪਣੇ ਖਾਤੇ ਦੇ ਪ੍ਰਮਾਣ ਪੱਤਰਾਂ, ਪ੍ਰੋਫਾਈਲ ਗਤੀਵਿਧੀ, ਅੱਪਲੋਡ ਕੀਤੀ ਸਮੱਗਰੀ, ਟਿੱਪਣੀਆਂ, ਸੁਨੇਹਿਆਂ ਅਤੇ ਤੁਹਾਡੇ ਖਾਤੇ ਤੋਂ ਕੀਤੇ ਗਏ ਕਿਸੇ ਵੀ ਸਿਰਜਣਹਾਰ ਜਾਂ ਪ੍ਰਬੰਧਕ ਕਾਰਵਾਈਆਂ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਹੋ। ਮਜ਼ਬੂਤ ​​ਪਾਸਵਰਡ ਵਰਤੋ ਅਤੇ ਦੋ-ਕਾਰਕ ਡਿਲੀਵਰੀ ਵਿਧੀਆਂ ਨੂੰ ਮੌਜੂਦਾ ਰੱਖੋ।',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'ਤੁਸੀਂ ਆਪਣੀਆਂ ਬ੍ਰਾਊਜ਼ਰ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਬ੍ਰਾਊਜ਼ਰ ਕੂਕੀਜ਼ ਅਤੇ ਸਥਾਨਕ ਸਟੋਰੇਜ ਨੂੰ ਸਾਫ਼ ਕਰ ਸਕਦੇ ਹੋ। ਜ਼ਰੂਰੀ ਸਟੋਰੇਜ ਨੂੰ ਕਲੀਅਰ ਕਰਨ ਨਾਲ ਤੁਸੀਂ ਸਾਈਨ ਆਉਟ ਕਰ ਸਕਦੇ ਹੋ, ਭਾਸ਼ਾ/ਥੀਮ ਤਰਜੀਹਾਂ ਨੂੰ ਰੀਸੈਟ ਕਰ ਸਕਦੇ ਹੋ, ਸਥਾਨਕ ਪਲੇਬੈਕ ਸਥਿਤੀ ਨੂੰ ਹਟਾ ਸਕਦੇ ਹੋ, ਅਤੇ ਤੁਹਾਨੂੰ ਦੁਬਾਰਾ ਲੌਗ ਇਨ ਕਰਨ ਦੀ ਲੋੜ ਹੋ ਸਕਦੀ ਹੈ।',
  'You receive a response by email.' => 'ਤੁਹਾਨੂੰ ਈਮੇਲ ਦੁਆਰਾ ਇੱਕ ਜਵਾਬ ਪ੍ਰਾਪਤ ਹੁੰਦਾ ਹੈ.',
  'You’re in control' => 'ਤੁਸੀਂ ਕੰਟਰੋਲ ਵਿੱਚ ਹੋ',
  'Your choices' => 'ਤੁਹਾਡੀਆਂ ਚੋਣਾਂ',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'ਤੁਹਾਡਾ ਸੁਨੇਹਾ ਸਿੱਧਾ ਵੈਬਸਾਈਟ ਬੈਕਐਂਡ ਵਿੱਚ ਸੁਰੱਖਿਅਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਸਹਾਇਤਾ ਦੇ ਅਧੀਨ ਐਡਮਿਨ ਡੈਸ਼ਬੋਰਡ ਵਿੱਚ ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ।',
