  'Import URL host cannot be resolved.' => 'ਆਯਾਤ URL ਹੋਸਟ ਨੂੰ ਹੱਲ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।',
  'Import URL must resolve to a public host.' => 'ਆਯਾਤ URL ਨੂੰ ਇੱਕ ਜਨਤਕ ਹੋਸਟ ਨੂੰ ਹੱਲ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ।',
  'Unknown video import provider.' => 'ਅਗਿਆਤ ਵੀਡੀਓ ਆਯਾਤ ਪ੍ਰਦਾਤਾ।',
