  'Fetches YouTube details and plays with the YouTube embed player.' => 'YouTube ਵੇਰਵੇ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ ਅਤੇ YouTube ਏਮਬੇਡ ਪਲੇਅਰ ਨਾਲ ਚਲਾਉਂਦਾ ਹੈ।',
  'Fetches Vimeo details and plays with the Vimeo embed player.' => 'Vimeo ਵੇਰਵੇ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ ਅਤੇ Vimeo ਏਮਬੇਡ ਪਲੇਅਰ ਨਾਲ ਖੇਡਦਾ ਹੈ।',
  'Fetches Dailymotion details and plays with the Dailymotion embed player.' => 'ਡੇਲੀਮੋਸ਼ਨ ਵੇਰਵੇ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ ਅਤੇ ਡੇਲੀਮੋਸ਼ਨ ਏਮਬੇਡ ਪਲੇਅਰ ਨਾਲ ਖੇਡਦਾ ਹੈ।',
