  'Saving provider video' => 'ਪ੍ਰਦਾਤਾ ਵੀਡੀਓ ਨੂੰ ਸੁਰੱਖਿਅਤ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ',
  'Fetched from provider' => 'ਪ੍ਰਦਾਤਾ ਤੋਂ ਪ੍ਰਾਪਤ ਕੀਤਾ',
